package com.dentalcrm.patient;
import org.junit.jupiter.api.Test; import java.time.LocalDate; import java.util.Optional; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class PatientServiceTest {@Test void editsPatientInPlaceWithoutDeletingHistory(){PatientRepository repo=mock(PatientRepository.class);Patient patient=new Patient();patient.setId(1L);patient.setFullName("Old");patient.setPhone("1");when(repo.findById(1L)).thenReturn(Optional.of(patient));PatientService service=new PatientService(repo);var result=service.update(1L,new PatientDtos.PatientRequest("New Name","0555",LocalDate.of(1990,1,1),"note"));assertEquals("New Name",result.fullName());assertEquals("0555",patient.getPhone());verify(repo,never()).delete(any());}}
